canonicalChanges.new:
/* Keep image result subtitles readable in Resize and history. */
.portal-page:is(.portal-image-resize, .portal-image-operation-history) .portal-document-operation-card .portal-document-operation-title .portal-card-subtitle {
  white-space: normal;
  overflow-wrap: anywhere;
  overflow: visible;
  text-overflow: clip;
}

/* Keep the file hint readable against the dark dropzone in every interaction state. */
html[data-portal-theme="dark"] .portal-page.portal-asset-vault .portal-vault-dropzone small {
  color: var(--portal-ink);
}

